// ── Lo único que se cambia a mano ───────────────────────────────────────────
const ENTORNO = 'sandbox';      // 'sandbox' o 'produccion'. La credencial de «Cola riesgo» y «Cola contratos» tiene que ser del mismo entorno.
const ACTIVAR = false;          // true: el script escribe en HubSpot. false: modo sombra (decide y registra, no escribe).
const IGNORAR_HORARIO = false;  // true solo para probar fuera de 7:30 a 4:30 o en festivos.
// ────────────────────────────────────────────────────────────────────────────

// Los objetos cambian de ID entre el sandbox y producción; las pipelines y las etapas no.
const OBJETOS = {
  sandbox:    { riesgo: '2-69460772', contratos: '2-69460784' },
  produccion: { riesgo: '2-72940686', contratos: '2-72940670' },
};
const RIESGO = { pipeline: '935982430', asignacion: '1439946540', aplazado: '1439946543' };
const CONTRATOS = { pipeline: '953891442', asignacion: '1472969116' };

const objetos = OBJETOS[ENTORNO];
if (!objetos) throw new Error(`ENTORNO debe ser 'sandbox' o 'produccion', no '${ENTORNO}'.`);
const igual = (propertyName, value) => ({ propertyName, operator: 'EQ', value });
const sinPropietario = { propertyName: 'hubspot_owner_id', operator: 'NOT_HAS_PROPERTY' };
const url = (objeto) => `https://api.hubapi.com/crm/objects/2026-09/${objeto}/search`;

// Las mismas colas que lee el script (FLUJOS y filtrosCola en asignacion_equilibrada.ts).
return [{
  json: {
    entorno: ENTORNO,
    riesgo: {
      url: url(objetos.riesgo),
      cuerpo: {
        filterGroups: [
          // Asignacion de analista, sin propietario
          { filters: [igual('hs_pipeline', RIESGO.pipeline), igual('hs_pipeline_stage', RIESGO.asignacion), sinPropietario] },
          // Aplazado por el motor, sin propietario (los aplazados de la migración no tienen resultado del motor)
          { filters: [igual('hs_pipeline', RIESGO.pipeline), igual('hs_pipeline_stage', RIESGO.aplazado), igual('analisis_resultado_motor', 'Aplazado'), sinPropietario] },
        ],
        limit: 1,
      },
    },
    contratos: {
      url: url(objetos.contratos),
      // Asignación de ejecutivo, con o sin propietario
      cuerpo: { filterGroups: [{ filters: [igual('hs_pipeline', CONTRATOS.pipeline), igual('hs_pipeline_stage', CONTRATOS.asignacion)] }], limit: 1 },
    },
    opciones: [ENTORNO === 'produccion' ? '--produccion' : '', ACTIVAR ? '--activar' : '', IGNORAR_HORARIO ? '--ignorar-horario' : ''].filter(Boolean).join(' '),
  },
}];

const config = $('Configuración').first().json;
const riesgo = $('Cola riesgo').first().json.total ?? 0;
const contratos = $('Cola contratos').first().json.total ?? 0;

const flujos = [];
if (riesgo > 0) flujos.push('analisis_riesgo');
if (contratos > 0) flujos.push('contratos');

return [{
  json: {
    entorno: config.entorno,
    riesgo,
    contratos,
    flujos,
    argumentos: [config.opciones, ...flujos.map((f) => `--flujo ${f}`)].filter(Boolean).join(' '),
  },
}];
